const UA_SEC = 'IRIS Research greyson@mccourtai.com';
const UA_BROWSER = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36';
const SB = $vars.IRIS_SUPABASE_URL; const KEY = $vars.IRIS_SUPABASE_SERVICE_ROLE_KEY;
const hIris = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };
const rpcIris = (fn, body) => this.helpers.httpRequest({ method:'POST', url: SB + '/rest/v1/rpc/' + fn, headers: hIris, json: true, timeout: 15000, body });
const out = { collected_at: new Date().toISOString(), sources: {} };
const get = (url, headers, asJson) => this.helpers.httpRequest({ method: 'GET', url, headers: headers || {}, timeout: 25000, json: !!asJson });

let TASK = null, PROMPT = null;
try { TASK = await rpcIris('iris_task_start', { p_agent:'analyst-invest', p_kind:'hunt', p_title:'Nightly market sweep ' + new Date().toISOString().slice(0,10), p_org_slug:'greyson-personal', p_max_classification:'client_confidential', p_input:{}, p_dedupe_key:null }); } catch(e){ out.task_note = 'task_start failed: ' + String(e.message).slice(0,80); }
try { PROMPT = await rpcIris('iris_get_prompt', { p_slug: 'analyst-invest.score' }); } catch(e){}
if (!PROMPT) PROMPT = 'Registry unavailable. Score conservatively; file nothing above 60; every opportunity needs an observable invalidation.';

// 1) FINRA daily short volume
try {
  const d = new Date(); const ymd = d.toISOString().slice(0,10).replace(/-/g,'');
  const txt = await get('https://cdn.finra.org/equity/regsho/daily/CNMSshvol' + ymd + '.txt');
  const lines = String(txt).trim().split('\n'); lines.shift(); lines.pop();
  let sv=0, tv=0; const n=lines.length;
  for (const l of lines){ const p=l.split('|'); sv+=parseFloat(p[2])||0; tv+=parseFloat(p[4])||0; }
  out.sources.finra_short_volume = { status:'ok', symbols:n, market_short_ratio: tv>0? +(sv/tv).toFixed(3):null, note:'short volume ratio is mostly MM plumbing; only multi-week deviations matter' };
} catch(e){ out.sources.finra_short_volume = { status:'skip', why:String(e.message).slice(0,80) }; }

// 2) EDGAR Form 4 current filings
try {
  const atom = await get('https://www.sec.gov/cgi-bin/browse-edgar?action=getcurrent&type=4&count=100&output=atom', { 'User-Agent': UA_SEC });
  const titles = [...String(atom).matchAll(/<title>4(?:\/A)? - ([^<]+) \((\d{7,10})\) \((Issuer|Reporting)\)<\/title>/g)];
  const issuers = {};
  for (const m of titles){ if (m[3]==='Issuer'){ issuers[m[1]] = (issuers[m[1]]||0)+1; } }
  const active = Object.entries(issuers).sort((a,b)=>b[1]-a[1]).slice(0,12).map(([name,filings])=>({name, filings}));
  out.sources.edgar_form4 = { status:'ok', recent_filings: titles.filter(t=>t[3]==='Issuer').length, most_active_issuers: active, note:'counts only — transaction codes not parsed; attention flags at most' };
} catch(e){ out.sources.edgar_form4 = { status:'skip', why:String(e.message).slice(0,80) }; }

// 3) Nasdaq earnings — next 2 days
try {
  const days=[];
  for (let i=1;i<=2;i++){ const dt=new Date(Date.now()+i*86400000).toISOString().slice(0,10); days.push(dt); }
  const rows=[];
  for (const dt of days){
    const j = await get('https://api.nasdaq.com/api/calendar/earnings?date='+dt, { 'User-Agent': UA_BROWSER, 'Accept':'application/json, text/plain, */*', 'Origin':'https://www.nasdaq.com', 'Referer':'https://www.nasdaq.com/' }, true);
    const rs = (j && j.data && j.data.rows) ? j.data.rows : [];
    for (const r of rs){ const mc=parseFloat(String(r.marketCap||'').replace(/[$,]/g,''))||0; rows.push({date:dt, symbol:r.symbol, time:r.time, mktcap_b:+(mc/1e9).toFixed(1)}); }
  }
  rows.sort((a,b)=>b.mktcap_b-a.mktcap_b);
  out.sources.earnings_next_48h = { status:'ok', count: rows.length, largest: rows.slice(0,15) };
} catch(e){ out.sources.earnings_next_48h = { status:'skip', why:String(e.message).slice(0,80) }; }

// 4) Sector rotation vs SPY
try {
  const syms=['SPY','XLK','XLE','XLF','XLV','XLI','XLP','XLY','XLU','XLB','XLRE','XLC'];
  const perf={};
  for (const s of syms){
    const j = await get('https://query1.finance.yahoo.com/v8/finance/chart/'+s+'?range=1mo&interval=1d', { 'User-Agent': UA_BROWSER }, true);
    const q=j.chart.result[0].indicators.quote[0].close.filter(x=>x!=null);
    if (q.length>=6){ perf[s]={ d5:+((q[q.length-1]/q[q.length-6]-1)*100).toFixed(2), d21:+((q[q.length-1]/q[0]-1)*100).toFixed(2), px:+q[q.length-1].toFixed(2) }; }
  }
  const spy=perf.SPY||{d21:0,d5:0};
  const rotation=Object.entries(perf).filter(([s])=>s!=='SPY').map(([s,p])=>({sector:s, rel_21d:+(p.d21-spy.d21).toFixed(2), rel_5d:+(p.d5-spy.d5).toFixed(2)})).sort((a,b)=>b.rel_21d-a.rel_21d);
  out.sources.rotation = { status:'ok', spy: spy, leaders: rotation.slice(0,3), laggards: rotation.slice(-3) };
} catch(e){ out.sources.rotation = { status:'skip', why:String(e.message).slice(0,80) }; }

// 5) GEX from CBOE free chain
try {
  const j = await get('https://cdn.cboe.com/api/global/delayed_quotes/options/SPY.json', { 'User-Agent': UA_BROWSER }, true);
  const spot = j.data.current_price;
  const strikes = {};
  let net = 0;
  for (const o of j.data.options){
    const sym = o.option || '';
    const cp = sym.charAt(sym.length-9);
    const strike = parseInt(sym.slice(-8),10)/1000;
    if (!strike || (cp!=='C' && cp!=='P')) continue;
    const g = (o.gamma||0) * (o.open_interest||0) * 100 * spot * spot * 0.01;
    const signed = cp==='C' ? g : -g;
    net += signed;
    if (Math.abs(strike-spot)/spot <= 0.12){ strikes[strike] = (strikes[strike]||0) + signed; }
  }
  const entries = Object.entries(strikes).map(([k,v])=>({strike:+k, gex_m:+(v/1e6).toFixed(1)}));
  const above = entries.filter(e=>e.strike>spot).sort((a,b)=>b.gex_m-a.gex_m);
  const below = entries.filter(e=>e.strike<spot).sort((a,b)=>a.gex_m-b.gex_m);
  out.sources.gex_spy = { status:'ok', spot:+spot.toFixed(2), net_gex_bn:+(net/1e9).toFixed(2), regime: net>0?'positive (mean-reverting, pinning)':'NEGATIVE (amplifying)', call_wall: above[0]||null, put_wall: below[0]||null, note:'naive dealer-sign model, OI-based (0DTE invisible)' };
} catch(e){ out.sources.gex_spy = { status:'skip', why:String(e.message).slice(0,80) }; }

if (TASK){ try { await rpcIris('iris_task_event', { p_task_id: TASK, p_event: 'collected', p_detail: { statuses: Object.fromEntries(Object.entries(out.sources).map(([k,v])=>[k, v.status])), prompt_live: PROMPT.length > 200 } }); } catch(e){} }
out._task_id = TASK;
out._prompt = PROMPT;
return [{ json: out }];

