const SB = $vars.IRIS_SUPABASE_URL;
const KEY = $vars.IRIS_SUPABASE_SERVICE_ROLE_KEY;
if (!SB || !KEY) throw new Error('IRIS vars missing');
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };
const rpc = (fn, body) => this.helpers.httpRequest({ method:'POST', url: SB + '/rest/v1/rpc/' + fn, headers: h, json: true, timeout: 20000, body });
const first = $input.first().json || {};
const o = first.output || first;
const brief = o.regime_brief || '';
const opps = Array.isArray(o.opportunities) ? o.opportunities : [];
const today = new Date().toISOString().slice(0,10);
let taskId = null;
try { taskId = $('Collect Official Feeds').first().json._task_id || null; } catch(e){}
let ingested = null;
if (brief && brief.length > 40) {
  ingested = await rpc('iris_ingest_document', { p_org_slug: 'greyson-personal', p_title: 'Market brief ' + today, p_body: brief, p_kind: 'note', p_classification: 'client_confidential', p_uri: null, p_metadata: { kind: 'market_brief', agent: 'analyst-invest' }, p_workflow: 'scout-markets' });
}
const filed = [];
for (const op of opps) {
  if (!op || typeof op.score !== 'number' || op.score < 65) continue;
  const id = await rpc('iris_file_claim', { p_agent: 'analyst-invest', p_kind: 'lead', p_statement: '[' + op.score + '] ' + String(op.symbol||'?') + ' — ' + String(op.reason||'').slice(0,120), p_detail: 'Invalidation: ' + (op.invalidation||'?') + '\nSignal: ' + (op.signal_source||'?'), p_confidence: Math.min(0.99, op.score/100), p_org_slug: 'greyson-personal' });
  filed.push({ claim_id: id, symbol: op.symbol, score: op.score });
}
if (taskId) { try { await rpc('iris_task_finish', { p_task_id: taskId, p_status: 'done', p_result: { brief_ingested: !!ingested, opportunities_reviewed: opps.length, claims_filed: filed.length }, p_error: null }); } catch(e){} }
return [{ json: { task_id: taskId, brief_ingested: !!ingested, opportunities_reviewed: opps.length, claims_filed: filed.length, filed } }];
